/*
 * The two config structs mnld passes to mtk_gps_mnl_run() on this phone
 * (MT6771 + MT6631), captured from the stock mnld with tools/gnss/mnlspy.c
 * and generated by hand from that dump. Known fields:
 *
 * init cfg (0x60 bytes)
 *   0x14 u16 PPS duty (100)            0x17 u8 clock type: 0xFE co-clock, 0xFF TCXO
 *   0x18 u16 clock drift ppb (2000)    0x1c u32 clock Hz (26 MHz)
 *   0x20 u32 link speed (115200)       0x24 u32 fix interval ms (1000)
 *   0x2c u32 chip key (0x170 = MT6771) 0x34 u32 chip id (0xffff6771)
 *   0x3c GNSS mode (2)                 0x40..0x4c clock calibration C0, C1,
 *   0x58 u32 eLNA pin (ioctl 0x10)       initU, lastU (0: no NVRAM file)
 * driver cfg (0x434 bytes): data file paths under /data/vendor/gps/, the
 *   DSP device name, log size limits, an extension block (magic 0xAA55,
 *   version 0x0102), and at 0x280 the open /dev/stpgps fd.
 */
#define INIT_CFG_SIZE 0x60
#define DRIVER_CFG_SIZE 0x434
#define MNL_RUN_OK 0x12

#define INIT_CLOCK_TYPE 0x17
#define INIT_LNA_PIN 0x58
#define DRV_DSP_FD 0x280

/* COMBO_IOC_* on /dev/stpgps */
#define IOC_RTC_FLAG 10
#define IOC_CO_CLOCK_FLAG 11
#define IOC_GPS_LNA_PIN 16

