/* per-boot values, as linux_gps_init() gets them */
static void config_probe(int fd, u8 *init, u8 *drv)
{
	int clk, pin = 0;

	ioctl(fd, IOC_RTC_FLAG, 0);
	/* clock flag: 0x00/0x10/.../0x40 TCXO, 0x01/0x11/.../0x41 co-clock
	 * (high nibble: buffer), 2 and 3 TCXO; mnld treats anything else
	 * as co-clock */
	clk = ioctl(fd, IOC_CO_CLOCK_FLAG, 0) & 0xff;
	if (clk == 2 || clk == 3 || (clk <= 0x40 && (clk & 0x0f) == 0))
		init[INIT_CLOCK_TYPE] = 0xff;
	else
		init[INIT_CLOCK_TYPE] = 0xfe;
	if (ioctl(fd, IOC_GPS_LNA_PIN, &pin) >= 0)
		memcpy(init + INIT_LNA_PIN, &pin, 4);
	memcpy(drv + DRV_DSP_FD, &fd, 4);
	say("titan-mnld: clock type 0x%x (%s), eLNA pin %d", clk,
	    init[INIT_CLOCK_TYPE] == 0xfe ? "co-clock" : "TCXO", pin);
}
